import React, { useEffect, useMemo, useState } from 'react';
import './dashboard.css';
import { getNotifications, getProjects, getTasks, markNotificationRead } from './api';
import Tasks from './task';
import Notification from './notification';

const menuItems = ['Dashboard', 'Tasks', 'Notifications', 'Projects'];

function Dashboard({ user, userName = 'there', userRole = 'User', onLogout }) {
  const [activeTab, setActiveTab] = useState('Dashboard');
  const [tasks, setTasks] = useState([]);
  const [projects, setProjects] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [toastAlert, setToastAlert] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [search, setSearch] = useState('');

  const isAdmin = userRole === 'Admin' || userRole === 'Manager';

  async function loadDashboard() {
    setLoading(true);
    setError('');

    try {
      const [taskResponse, projectResponse, notificationResponse] = await Promise.all([
        getTasks(),
        getProjects(),
        getNotifications(),
      ]);

      const fetchedTasks = Array.isArray(taskResponse?.data) ? taskResponse.data : [];
      const fetchedProjects = Array.isArray(projectResponse?.data) ? projectResponse.data : [];
      const fetchedNotifications = Array.isArray(notificationResponse?.data) ? notificationResponse.data : [];

      setTasks(fetchedTasks);
      setProjects(fetchedProjects);
      setNotifications(fetchedNotifications);

      // Check for unread task assignment notification for toast pop-up
      const unreadTaskNotice = fetchedNotifications.find(n => !n.read && n.type === 'task');
      if (unreadTaskNotice) {
        setToastAlert(unreadTaskNotice);
      }
    } catch (err) {
      setError(err.message || 'Unable to load dashboard data.');
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    loadDashboard();
    const interval = setInterval(loadDashboard, 12000);
    return () => clearInterval(interval);
  }, []);

  async function closeToast() {
    if (toastAlert?._id) {
      try {
        await markNotificationRead(toastAlert._id);
      } catch (err) {
        console.error(err);
      }
    }
    setToastAlert(null);
  }

  const dashboard = useMemo(() => {
    const totalTasks = tasks.length;
    const completed = tasks.filter(isCompleted).length;
    const inProgress = tasks.filter((task) => task.status === 'in-progress').length;
    const pending = Math.max(totalTasks - completed - inProgress, 0);
    const overdue = tasks.filter(isOverdue).length;

    const priority = {
      high: tasks.filter((task) => task.priority === 'high').length,
      medium: tasks.filter((task) => task.priority === 'medium').length,
      low: tasks.filter((task) => task.priority === 'low').length,
    };

    return {
      totalTasks,
      activeProjects: projects.length,
      completed,
      inProgress,
      pending,
      overdue,
      priority,
    };
  }, [projects, tasks]);

  const statusCards = [
    { label: 'Pending', value: dashboard.pending, color: 'sand', percent: percentOf(dashboard.pending, dashboard.totalTasks) },
    { label: 'In Progress', value: dashboard.inProgress, color: 'orange', percent: percentOf(dashboard.inProgress, dashboard.totalTasks) },
    { label: 'Completed', value: dashboard.completed, color: 'green', percent: percentOf(dashboard.completed, dashboard.totalTasks) },
  ];

  const visibleTasks = useMemo(() => {
    const query = search.trim().toLowerCase();
    if (!query) return tasks;
    return tasks.filter((task) => {
      const haystack = [
        task.title,
        task.description,
        task.priority,
        task.status,
        task.assignedUser?.fullname,
        task.assignedUser?.username,
      ].filter(Boolean).join(' ').toLowerCase();
      return haystack.includes(query);
    });
  }, [search, tasks]);

  const workloadRows = buildWorkloadRows(tasks, userName);
  const unreadNotificationsCount = notifications.filter((item) => !item.read).length;
  const firstName = String(userName || 'there').split(' ')[0];

  return (
    <div className="dashboard-page">
      {/* Toast Notification Banner Alert */}
      {toastAlert && (
        <div className="toast-container">
          <div className="toast-card">
            <div className="toast-icon">🔔</div>
            <div className="toast-content">
              <strong>{toastAlert.title || 'New Task Assigned!'}</strong>
              <p>{toastAlert.message || 'An Admin assigned a task to you.'}</p>
            </div>
            <button className="toast-close" onClick={closeToast}>✕</button>
          </div>
        </div>
      )}

      <div className="dashboard-shell">
        {/* Sidebar */}
        <aside className="dashboard-sidebar">
          <div className="brand-card">
            <div className="brand-mark">TM</div>
            <strong>Task Management</strong>
          </div>

          <nav className="side-nav" aria-label="Main navigation">
            <p>Menu</p>
            {menuItems.map((item) => (
              <button
                className={`nav-item ${activeTab === item ? 'active' : ''}`}
                type="button"
                key={item}
                onClick={() => setActiveTab(item)}
              >
                <span>{getMenuIcon(item)}</span>
                {item}
                {item === 'Notifications' && unreadNotificationsCount > 0 && (
                  <b className="unread-badge">{unreadNotificationsCount}</b>
                )}
              </button>
            ))}
          </nav>

          <div className="sidebar-footer">
            <button className="nav-item logout-btn" type="button" onClick={onLogout}>
              <span>🚪</span>
              Logout
            </button>
          </div>
        </aside>

        {/* Main Content Area */}
        <main className="dashboard-main">
          {/* Top Bar */}
          <header className="dashboard-topbar">
            <div>
              <h1>Welcome back, {firstName} 👋</h1>
              <p>Role: <strong className="user-role-tag">{userRole}</strong> | {isAdmin ? 'Workspace Admin Overview' : 'Assigned Member Dashboard'}</p>
            </div>

            <label className="search-box">
              <span>🔍</span>
              <input
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder="Search tasks..."
                type="search"
              />
            </label>

            <button
              className="notification-button"
              type="button"
              onClick={() => setActiveTab('Notifications')}
              title="Notifications"
            >
              🔔
              {unreadNotificationsCount > 0 && <b>{unreadNotificationsCount}</b>}
            </button>

            <div className="account-box">
              <div className="user-avatar">{getInitials(userName)}</div>
              <div>
                <strong>{userName}</strong>
                <small>{user?.email || userRole}</small>
              </div>
            </div>
          </header>

          {error && <div className="dashboard-alert">{error}</div>}

          {/* DASHBOARD TAB */}
          {activeTab === 'Dashboard' && (
            <>
              {/* REAL-TIME METRICS GRID */}
              <section className="metric-grid">
                <MetricCard title="Total Tasks" value={dashboard.totalTasks} helper="Tasks in workspace" tone="sand" loading={loading} />
                <MetricCard title="Pending Tasks" value={dashboard.pending} helper="Awaiting progress" tone="peach" loading={loading} />
                <MetricCard title="In Progress" value={dashboard.inProgress} helper="Currently being worked on" tone="blush" loading={loading} />
                <MetricCard title="Completed Tasks" value={dashboard.completed} helper="Finished successfully" tone="mint" loading={loading} />
              </section>

              {/* STATUS BREAKDOWN & PRIORITY */}
              <div className="dashboard-grid">
                <section className="panel status-panel">
                  <PanelHeader title="Task Status Breakdown" helper="Real-time completion & status metric" />
                  <div className="status-bars">
                    {statusCards.map((item) => (
                      <div className={`status-card ${item.color}`} key={item.label}>
                        <span>{item.label}</span>
                        <strong>{item.value} ({item.percent}%)</strong>
                        <div><i style={{ width: `${item.percent}%` }} /></div>
                      </div>
                    ))}
                  </div>
                </section>

                <section className="panel priority-panel">
                  <PanelHeader title="Priority Distribution" helper="Breakdown by urgency" />
                  <PriorityDonut priority={dashboard.priority} total={dashboard.totalTasks} />
                </section>
              </div>

              {/* TEAM WORKLOAD METRIC */}
              <div className="dashboard-grid bottom-grid">
                <section className="panel workload-panel full-span">
                  <PanelHeader
                    title="Team Workload & Assignment Metrics"
                    helper={isAdmin ? "Overview of active tasks per team member" : "Your active workload overview"}
                  />
                  <div className="workload-table">
                    <div className="workload-head">
                      <span>Team Member</span>
                      <span>Active Tasks</span>
                      <span>Overdue</span>
                      <span>Workload Status</span>
                    </div>

                    {loading ? (
                      <LoadingRows />
                    ) : workloadRows.length ? workloadRows.map((row) => (
                      <div className="workload-row" key={row.name}>
                        <div className="person-cell">
                          <div className="person-avatar">{getInitials(row.name)}</div>
                          <div>
                            <strong>{row.name}</strong>
                            <small>{row.role}</small>
                          </div>
                        </div>
                        <span>{row.active} tasks</span>
                        <span>{row.overdue} overdue</span>
                        <span className={`workload-status ${row.tone}`}>{row.status}</span>
                      </div>
                    )) : (
                      <div className="empty-state">No active workload data.</div>
                    )}
                  </div>
                </section>
              </div>

              {/* RECENT TASKS PANEL */}
              <section className="panel task-panel">
                <div className="panel-heading flex-between">
                  <div>
                    <h2>Recent Tasks</h2>
                    <p>Live status updates from task list</p>
                  </div>
                  <button className="btn-secondary" type="button" onClick={() => setActiveTab('Tasks')}>
                    View All Tasks →
                  </button>
                </div>
                <div className="task-list">
                  {loading ? (
                    <LoadingRows />
                  ) : visibleTasks.length ? visibleTasks.slice(0, 5).map((task) => (
                    <TaskRow task={task} key={task._id || task.id || task.title} />
                  )) : (
                    <div className="empty-state">{search ? 'No matching tasks.' : 'No tasks created yet.'}</div>
                  )}
                </div>
              </section>
            </>
          )}

          {/* TASKS TAB */}
          {activeTab === 'Tasks' && (
            <Tasks user={user} onTaskAssigned={loadDashboard} />
          )}

          {/* NOTIFICATIONS TAB */}
          {activeTab === 'Notifications' && (
            <Notification onUnreadChange={(count) => {}} />
          )}

          {/* PROJECTS TAB */}
          {activeTab === 'Projects' && (
            <section className="panel">
              <PanelHeader title="Workspace Projects" helper="Active project categories" />
              <div className="task-list">
                {projects.length ? projects.map((p) => (
                  <div className="task-row" key={p._id || p.name}>
                    <div className="task-dot" />
                    <div>
                      <strong>{p.name}</strong>
                      <small>{p.description || 'General workspace project'}</small>
                    </div>
                    <span className="task-badge completed">{p.status || 'Active'}</span>
                  </div>
                )) : (
                  <div className="empty-state">No active projects created yet.</div>
                )}
              </div>
            </section>
          )}
        </main>
      </div>
    </div>
  );
}

function MetricCard({ title, value, helper, tone, loading }) {
  return (
    <article className={`metric-card ${tone}`}>
      <span>{title}</span>
      <strong>{loading ? '--' : value}</strong>
      <p>{helper}</p>
    </article>
  );
}

function PanelHeader({ title, helper }) {
  return (
    <div className="panel-heading">
      <div>
        <h2>{title}</h2>
        {helper && <p>{helper}</p>}
      </div>
    </div>
  );
}

function PriorityDonut({ priority, total }) {
  const high = percentOf(priority.high, total);
  const medium = percentOf(priority.medium, total);

  return (
    <div className="priority-container">
      <div
        className="priority-donut"
        style={{
          '--high': `${high}%`,
          '--medium': `${high + medium}%`,
        }}
      >
        <span>{total} Total</span>
      </div>
      <div className="priority-legend">
        <span><i className="high" />High: {priority.high}</span>
        <span><i className="medium" />Medium: {priority.medium}</span>
        <span><i className="low" />Low: {priority.low}</span>
      </div>
    </div>
  );
}

function TaskRow({ task }) {
  const assigneeName = task.assignedUser?.fullname || task.assignedUser?.username || 'Unassigned';
  return (
    <div className="task-row">
      <div className={`task-dot ${task.priority || 'medium'}`} />
      <div className="task-info">
        <strong>{task.title || 'Untitled task'}</strong>
        <small>Assigned to: <strong>{assigneeName}</strong></small>
      </div>
      <span className={`task-badge ${task.status || 'pending'}`}>
        {task.status === 'in-progress' ? 'In Progress' : (task.status || 'pending').charAt(0).toUpperCase() + (task.status || 'pending').slice(1)}
      </span>
    </div>
  );
}

function LoadingRows() {
  return (
    <div className="loading-rows-container">
      <div className="loading-row" />
      <div className="loading-row" />
      <div className="loading-row" />
    </div>
  );
}

function buildWorkloadRows(tasks, fallbackName) {
  const grouped = new Map();

  tasks.forEach((task) => {
    const person = task.assignedUser || task.creator || {};
    const name = person.fullname || person.username || fallbackName || 'Team Member';
    const current = grouped.get(name) || {
      name,
      role: person.role || 'Member',
      active: 0,
      overdue: 0,
    };

    if (!isCompleted(task)) current.active += 1;
    if (isOverdue(task)) current.overdue += 1;
    grouped.set(name, current);
  });

  return Array.from(grouped.values()).map((row) => {
    if (row.overdue >= 2) return { ...row, status: 'Overloaded', tone: 'danger' };
    if (row.active >= 4) return { ...row, status: 'Busy', tone: 'busy' };
    return { ...row, status: 'Balanced', tone: 'good' };
  });
}

function isCompleted(task) {
  return Boolean(task.completed || task.status === 'completed');
}

function isOverdue(task) {
  if (!task.dueDate || isCompleted(task)) return false;
  const dueDate = new Date(task.dueDate);
  if (Number.isNaN(dueDate.getTime())) return false;
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  dueDate.setHours(0, 0, 0, 0);
  return dueDate < today;
}

function percentOf(value, total) {
  return total ? Math.round((value / total) * 100) : 0;
}

function getInitials(name) {
  return String(name || 'U')
    .split(' ')
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0])
    .join('')
    .toUpperCase();
}

function getMenuIcon(item) {
  const icons = {
    Dashboard: '📊',
    Tasks: '📋',
    Notifications: '🔔',
    Projects: '📁',
  };
  return icons[item] || '🔹';
}

export default Dashboard;
